-- Contas criadas antes das migrações (ex.: projeto reaproveitado) ganham o perfil que faltar.
select public.criar_perfis_das_contas();

update public.perfis p set perfil = v.perfil, nome = v.nome
from (values
  ('administrador@example.com', 'administrador', 'Administrador (demonstração)'),
  ('almoxarife@example.com', 'almoxarife', 'Almoxarife (demonstração)'),
  ('gestor@example.com', 'gestor', 'Gestor (demonstração)'),
  ('requisitante@example.com', 'requisitante', 'Requisitante (demonstração)')
) as v(email, perfil, nome)
where p.email = v.email;

do $$
declare
  v_faltam text;
begin
  select string_agg(v.email, ', ' order by v.ordem) into v_faltam
  from (values
    (1, 'administrador@example.com', 'administrador'),
    (2, 'almoxarife@example.com', 'almoxarife'),
    (3, 'gestor@example.com', 'gestor'),
    (4, 'requisitante@example.com', 'requisitante')
  ) as v(ordem, email, perfil)
  where not exists (select 1 from public.perfis p where p.email = v.email and p.perfil = v.perfil);
  if v_faltam is not null then
    raise exception 'Conta de demonstração não encontrada em Authentication › Users: %. Crie a conta (Add user, com Auto Confirm User) e execute o seed de novo.', v_faltam;
  end if;
end $$;

select public.carregar_demonstracao();
